.required::after {
  content: " *"; /* decorative only */
  color: red;
}

/* Put the actual required text/state in HTML, not only here */

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
